const ui={items:document.querySelector('#items'),counter:document.querySelector('#counter'),quest:document.querySelector('#quest-copy'),hint:document.querySelector('#hint'),footer:document.querySelector('#footer-note'),action:document.querySelector('#action'),label:document.querySelector('#action-label'),toast:document.querySelector('#toast'),dialogue:document.querySelector('#dialogue'),speaker:document.querySelector('#speaker'),line:document.querySelector('#line')};
for(const item of goodies){const chip=document.createElement('span');chip.className='item-chip';chip.id='chip-'+item.id;chip.textContent=item.emoji;chip.title=item.name;ui.items.appendChild(chip)}
function resize(){if(!renderer)return;const w=game.clientWidth,h=game.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();
const keys=new Set();let stick={x:0,y:0};
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if((e.key===' '||e.key==='e'||e.key==='Enter')&&!e.repeat)interact();});
addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
const stickEl=document.querySelector('#stick'),knob=document.querySelector('#knob');let stickPointer=null;
function moveStick(e){const r=stickEl.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.31,len=Math.hypot(dx,dy),scale=len>max?max/len:1;stick={x:dx*scale/max,y:dy*scale/max};knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
stickEl.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stickEl.setPointerCapture(e.pointerId);moveStick(e)});
stickEl.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e)});
function releaseStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;stick={x:0,y:0};knob.style.transform=''}stickEl.addEventListener('pointerup',releaseStick);stickEl.addEventListener('pointercancel',releaseStick);
document.querySelector('#action').addEventListener('click',interact);
document.querySelector('#start').addEventListener('click',()=>{document.querySelector('#welcome').classList.remove('open');started=true;showToast('Find the five glowing picnic treats!');});
document.querySelector('#replay').addEventListener('click',()=>location.reload());
document.querySelector('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'🔔':'♫';showToast(soundOn?'Sound on!':'Sound off');});
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function showDialogue(name,text){ui.speaker.textContent=name;ui.line.textContent=text;ui.dialogue.classList.add('show');clearTimeout(dialogueTimer);dialogueTimer=setTimeout(()=>ui.dialogue.classList.remove('show'),3500)}
function distanceTo(x,z){return Math.hypot(player.position.x-x,player.position.z-z)}
function nearby(){let closest=null,d=2.2;for(const p of pickups){if(!p.got&&distanceTo(p.item.x,p.item.z)<d){closest={kind:'item',target:p,d:distanceTo(p.item.x,p.item.z)};d=closest.d;}}for(const n of family){const nd=distanceTo(n.x,n.z);if(nd<2.1&&nd<d){closest={kind:'family',target:n,d:nd};d=nd;}}if(distanceTo(5,4)<2.6&&goodies.every(g=>pickups.find(p=>p.item.id===g.id).got)){closest={kind:'picnic',target:null,d:distanceTo(5,4)}}return closest}
function refreshQuest(){const count=pickups.filter(p=>p.got).length;ui.counter.textContent=`${count} / 5`;for(const p of pickups)document.querySelector('#chip-'+p.item.id).classList.toggle('got',p.got);if(count<5){ui.quest.textContent=count===0?'Find the picnic treats, then meet your family at the blanket.':`Lovely! ${5-count} more ${5-count===1?'treat':'treats'} to go. Keep exploring!`;ui.hint.innerHTML=`${5-count} picnic ${5-count===1?'treat':'treats'} left — look for the <strong>glowing rings</strong> ✨`}else{ui.quest.textContent='Everything is ready! Bring the goodies to your family’s blanket.';ui.hint.innerHTML='Head to the <strong>picnic blanket</strong> to celebrate! 🎉'}}
function interact(){if(!started||done)return;const n=nearby();if(!n){showToast('Look for a glowing treat or a family member nearby.');return}if(n.kind==='item'){const p=n.target;p.got=true;p.group.visible=false;document.querySelector('#chip-'+p.item.id).classList.add('got');refreshQuest();showToast(`${p.item.emoji} ${p.item.name} collected!`);if(soundOn)beep(680,.07);return}if(n.kind==='family'){const count=pickups.filter(p=>p.got).length;let line=n.target.line;if(count===5)line='You found everything! Let’s gather at the blanket and enjoy our picnic together. 🌼';else if(count>0)line=`You’ve found ${count} of 5 treats — wonderful exploring! ${n.target.name==='Riley'?'The picnic blanket is just nearby.':''}`;showDialogue(n.target.name,line);return}completeGame()}
function completeGame(){done=true;ui.dialogue.classList.remove('show');ui.footer.textContent='A DAY TO REMEMBER';document.querySelector('#finish').classList.add('open');sparkles.forEach((s,i)=>{s.visible=true;const a=i/22*Math.PI*2;s.position.set(5+Math.cos(a)*(1.2+(i%3)*.4),1.2+(i%4)*.35,4+Math.sin(a)*(1.1+(i%2)*.5))});if(soundOn){beep(784,.12);setTimeout(()=>beep(988,.16),160)}}
function beep(freq,duration){try{const ctx=new AudioContext(),o=ctx.createOscillator(),gain=ctx.createGain();o.type='sine';o.frequency.value=freq;gain.gain.setValueAtTime(.07,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(gain);gain.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration)}catch{}}
refreshQuest();
let moveAmount=0;
function tick(){requestAnimationFrame(tick);if(!renderer)return;const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;
let mx=stick.x+(keys.has('a')||keys.has('arrowleft')?-1:0)+(keys.has('d')||keys.has('arrowright')?1:0),mz=stick.y+(keys.has('w')||keys.has('arrowup')?-1:0)+(keys.has('s')||keys.has('arrowdown')?1:0);const mag=Math.hypot(mx,mz);if(mag>1){mx/=mag;mz/=mag}const speed=5.1;moveAmount=Math.hypot(mx,mz);if(started&&!done&&moveAmount>.04){player.position.x=THREE.MathUtils.clamp(player.position.x+mx*speed*dt,-13,13);player.position.z=THREE.MathUtils.clamp(player.position.z+mz*speed*dt,-11,11);player.rotation.y=Math.atan2(mx,mz);}
player.position.y=moveAmount>.04?Math.abs(Math.sin(t*11))*.06:0;player.userData.arms.forEach((a,i)=>a.rotation.x=moveAmount>.04?Math.sin(t*11+i*Math.PI)*.38:Math.sin(t*1.6+i*Math.PI)*.035);
for(let i=0;i<family.length;i++){const n=family[i];n.model.position.y=Math.sin(t*1.6+i)*.035;n.model.rotation.y=Math.sin(t*.6+i)*.08;}
for(const p of pickups)if(!p.got){p.group.position.y=Math.sin(t*2.7+goodies.indexOf(p.item))*.09;p.group.rotation.y=t*.4;}
const target=new THREE.Vector3(player.position.x,0,player.position.z);const camPos=new THREE.Vector3(player.position.x+0,player.position.y+13,player.position.z+17);camera.position.lerp(camPos,1-Math.pow(.0005,dt));camera.lookAt(target.x,1.0,target.z);
const near=started&&!done?nearby():null;if(near){ui.action.classList.add('ready');ui.label.textContent=near.kind==='item'?'PICK UP':near.kind==='family'?'SAY HI':'CELEBRATE';ui.hint.style.opacity='0';}else{ui.action.classList.remove('ready');ui.label.textContent='INTERACT';ui.hint.style.opacity='1';}
for(let i=0;i<sparkles.length;i++)if(sparkles[i].visible){const s=sparkles[i];s.rotation.x+=dt*1.8;s.rotation.y+=dt*2;s.position.y+=Math.sin(t*4+i)*dt*.12;}
renderer.render(scene,camera)}tick();
</script>
</body>
</html>

